using System;using System.Collections.Generic;using System.Diagnostics;using System.Text.RegularExpressions;
namespace ServiceTool{internal static class ServiceHttpSys{internal static List<string> Parse(string text,int pid){var urls=new List<string>();foreach(string block in Regex.Split(text,@"(?m)^(?=Request queue name:|Имя очереди запросов:)")){if(!Regex.IsMatch(block,@"(?m)^\s*(?:ID|ИД|Идентификатор):\s*"+pid+@"\s*,"))continue;foreach(Match match in Regex.Matches(block,@"(?im)^\s*(https?://[^\s]+)\s*$")){string raw=match.Groups[1].Value;raw=Regex.Replace(raw,@"(?i)^(https?://)[*+]", "$1localhost");Uri uri;if(Uri.TryCreate(raw,UriKind.Absolute,out uri)&&uri.IsLoopback&&String.IsNullOrEmpty(uri.UserInfo))urls.Add(uri.AbsoluteUri);}}return urls;}internal static List<string> Read(int pid){using(var process=Process.Start(new ProcessStartInfo("netsh.exe","http show servicestate view=requestq verbose=yes"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(5000)){process.Kill();return new List<string>();}if(process.ExitCode!=0)return new List<string>();return Parse(stdout.GetAwaiter().GetResult(),pid);}}}}
